/**
 * How long a dev server gets to answer. Giving up is only a report — the server is left running and
 * the rest of the run carries on — and machines are sometimes slow, so both are deliberately
 * generous: the budget counts from the spawn, and whatever is left of it, a server still gets the
 * grace period once the containers are up (see `readyDeadline`).
 */
const READY_TIMEOUT_MS = 300000;
const READY_GRACE_MS = 120000;
const READY_POLL_MS = 500;

/**
 * When to stop waiting for a dev server. There is no deadline while the containers are still coming
 * up (`waitingSince` is null): the frontends compile alongside the image build, compete with it for
 * the CPU, and on a cold run the build alone can take longer than any fixed budget. After that it is
 * the later of the budget from spawn and the grace period from when the wait began, so a slow
 * container phase never uses up a server's time before anyone has waited for it.
 */
export function readyDeadline({ startedAt, waitingSince, timeoutMs, graceMs }) {
  if (waitingSince === null) {
    return Infinity;
  } else {
    return Math.max(startedAt + timeoutMs, waitingSince + graceMs);
  }
}

// Longer than any answer a local dev server gives, and short enough that one probe never matters
// next to the deadline.
const PROBE_TIMEOUT_MS = 2000;

// What a port that is not serving yet looks like to `fetch`: nothing listening, or a listener that
// dropped the connection — Vite does both while it starts. Anything else is not "not yet".
const NOT_LISTENING_YET = new Set(['ECONNREFUSED', 'ECONNRESET', 'ECONNABORTED', 'EPIPE', 'UND_ERR_SOCKET']);

/**
 * Whether anything is serving HTTP on this port yet. Any response at all counts, including a 404:
 * the question is whether the dev server is answering, not what it thinks of `/`. A closed port
 * rejects, which reads as "not yet" rather than an error, because that is the normal state for the
 * first minute or two of a run — and so does a probe that got no answer in time: Vite binds its port
 * early and can hold a request for its whole first build.
 *
 * Deliberately addressed by IP rather than by the instance's public hostname: on Windows nothing
 * outside a browser resolves `*.localhost` (see the root README), so a hostname probe would time
 * out forever on exactly the platform this runs on. Vite answers a bare-IP `Host` regardless — its
 * `allowedHosts` check is DNS-rebinding protection, which always permits IP literals.
 */
export async function answersOnPort(port, { timeoutMs = PROBE_TIMEOUT_MS } = {}) {
  if (!Number.isInteger(port)) {
    throw new Error(`No port to probe (got ${port}) — the dev server's port was never allocated.`);
  } else {
    try {
      const response = await fetch(`http://127.0.0.1:${port}/`, { signal: AbortSignal.timeout(timeoutMs) });
      // Unread, the body would keep the connection checked out of the pool for as long as it lives.
      await response.body?.cancel();
      return true;
    } catch (error) {
      if (isNotListeningYet(error)) {
        return false;
      } else {
        throw error;
      }
    }
  }
}

function isNotListeningYet(error) {
  return error.name === 'TimeoutError' || NOT_LISTENING_YET.has(error.cause?.code);
}

/**
 * Polls until the dev server answers, is gone, or its deadline passes, reporting whether it answered
 * and how long it took. Asking the port is what keeps this free of any dependency on the dev server's
 * own output: no "ready in 1234ms" string to match, nothing to re-learn when Vite changes its
 * wording, and no risk of mistaking a compile error that mentions a URL for a readiness banner.
 *
 * The duration is measured from `startedAt`, when the server was spawned, and `deadline` is asked
 * again on every round, because it only comes into being while this loop is already running (see
 * `readyDeadline`).
 */
export async function waitForPort({
  port,
  startedAt,
  deadline,
  stopped = () => false,
  intervalMs = READY_POLL_MS,
  probe = answersOnPort,
  now = Date.now,
  sleep = (ms) => delay(ms),
}) {
  // Asked once before the clock is consulted: a server that is already up must be reported as such
  // however long it took to get there, and calling one unready without ever asking would be a guess.
  let ready = await probe(port);
  while (!ready && !stopped() && now() < deadline()) {
    await sleep(intervalMs);
    ready = await probe(port);
  }
  return { ready, elapsedMs: now() - startedAt };
}

/**
 * One server's readiness, watched from its launch: `ready` once it answers, `silent` if its deadline
 * passes first, `exited` if it dies before either. A dead server is not slow, and without the race
 * its closed port would be polled until the deadline and then described as "may still be building".
 */
function watchReadiness({ port, closed, isGone, startedAt, deadline, probe, now, sleep }) {
  const answered = waitForPort({ port, startedAt, deadline, stopped: isGone, probe, now, sleep }).then(
    ({ ready, elapsedMs }) => ({ state: ready ? 'ready' : 'silent', elapsedMs }),
  );
  const died = closed.then(() => ({ state: 'exited', elapsedMs: now() - startedAt }));
  const readiness = Promise.race([answered, died]);
  // Nobody awaits this until the containers are up, minutes later; a probe that throws in the
  // meantime must not become an unhandled rejection before then. The awaiting caller still sees it.
  readiness.catch(() => {});
  return readiness;
}

function launch({
  repoRoot,
  instance,
  name,
  project,
  ports,
  spawnProcess,
  platform,
  state,
  reportCrash,
  logFile,
  readinessOptions,
}) {
  const args = serveArgs({
    project,
    port: ports[name],
    hostname: publicHostname(instance, name),
  });
  const child = spawnProcess('pnpm', args, {
    cwd: join(repoRoot, 'app'),
    stdio: ['ignore', 'pipe', 'pipe'],
    ...treeSpawnOptions(platform),
  });
  const logPath = logFile(name);
  const capture = captureChild(child, { logFile: logPath });

  // 'close', not 'exit': the direct child is only `pnpm` (or the cmd.exe in front of it), and the nx
  // and Angular processes below it share its pipe and may still be writing when it exits. The last
  // lines are where the reason for a crash is, so both the report and the end of the log wait for
  // the pipe to drain — the same event `runCaptured` settles on.
  const closed = new Promise((resolve) => {
    child.on('close', (code, signal) => resolve({ code, signal }));
  });
  let gone = false;
  closed.then(({ code, signal }) => {
    gone = true;
    if (state.stopRequested) {
      // Part of a deliberate stop() - expected, and already covered by that call. Not a crash.
    } else {
      process.stderr.write(crashReport({ name, code, signal, tail: capture.tail, logFile: logPath }));
      reportCrash({ name, code, signal });
    }
  });

  const readiness = watchReadiness({
    port: ports[name],
    closed,
    isGone: () => gone || state.stopRequested,
    ...readinessOptions,
  });

  return { name, port: ports[name], logPath, child, closed, capture, readiness };
}

/**
 * The whole tree, not only the direct child (see `processtree.mjs`): the processes holding the port
 * are its descendants. SIGKILL after the grace period, and after that a second bounded wait rather
 * than an open-ended one — a descendant that survives even that would otherwise keep the pipe, and
 * with it Ctrl-C, open forever.
 */
